import CryptoKit
import XCTest
@testable import LeaveCryptoKit

/// LeaveCryptoCore against the shared vectors (vectors/v1.json, generated by Leave's server
/// code) and samples the server's own code produced on 2026-09-29 with fixed, made-up keys.
final class LeaveCryptoTests: XCTestCase {
  private var v: [String: Any] = [:]

  override func setUpWithError() throws {
    // vectors/v1.json at the top of this repository, the one file every implementation is held to.
    let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("../../../vectors/v1.json").standardized
    v = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    XCTAssertEqual(v["encoding"] as? String, "base64url-nopad")
  }

  private func b(_ s: String) throws -> Data { try XCTUnwrap(LeaveCryptoCore.fromBase64url(s), "not base64url: \(s.prefix(16))") }
  private func cases(_ kind: String) -> [[String: Any]] { (v[kind] as? [[String: Any]]) ?? [] }
  private func s(_ c: [String: Any], _ k: String) throws -> String { try XCTUnwrap(c[k] as? String, k) }

  func testRecordAead() throws {
    let all = cases("recordAead")
    XCTAssertFalse(all.isEmpty)
    for c in all {
      let aad = Data(try s(c, "aad").utf8)
      XCTAssertEqual(aad, LeaveCryptoCore.aad(try s(c, "recordType"), try s(c, "recordId")), c["name"] as? String ?? "")
      let wire = try LeaveCryptoCore.seal(key: try b(try s(c, "dek")), plaintext: try b(try s(c, "plaintext")), aad: aad, nonce: try b(try s(c, "nonce")))
      XCTAssertEqual(LeaveCryptoCore.base64url(wire), try s(c, "wire"), c["name"] as? String ?? "")
      XCTAssertEqual(try LeaveCryptoCore.open(key: try b(try s(c, "dek")), wire: try b(try s(c, "wire")), aad: aad), try b(try s(c, "plaintext")))
      XCTAssertThrowsError(try LeaveCryptoCore.open(key: try b(try s(c, "dek")), wire: try b(try s(c, "wire")), aad: Data("leave:v1:other:x".utf8)))
    }
  }

  /// The recovery blob: Argon2id 64 MiB, 3 passes, 1 lane, then
  /// AES-256-GCM with no associated data. The vector is the backend's.
  func testRecoveryBlob() throws {
    let all = cases("recovery")
    XCTAssertFalse(all.isEmpty)
    for c in all {
      let name = c["name"] as? String ?? ""
      let code = try s(c, "recoveryCode"), salt = try b(try s(c, "salt")), nonce = try b(try s(c, "nonce")), share = try b(try s(c, "share"))
      XCTAssertEqual(LeaveCryptoCore.base64url(try LeaveCryptoCore.recoveryKey(code: code, salt: salt)), try s(c, "key"), name)
      XCTAssertEqual(LeaveCryptoCore.base64url(try LeaveCryptoCore.sealRecovery(share: share, code: code, salt: salt, nonce: nonce)), try s(c, "blob"), name)
      XCTAssertEqual(try LeaveCryptoCore.openRecovery(blob: try b(try s(c, "blob")), code: code), share, name)
      // One wrong character opens nothing.
      let wrong = String(code.dropLast()) + (code.last == "0" ? "1" : "0")
      XCTAssertThrowsError(try LeaveCryptoCore.openRecovery(blob: try b(try s(c, "blob")), code: wrong), name)
      // A blob of another version or length is refused before any work is done.
      var other = try b(try s(c, "blob")); other[0] = 0x02
      XCTAssertThrowsError(try LeaveCryptoCore.openRecovery(blob: other, code: code))
      XCTAssertThrowsError(try LeaveCryptoCore.openRecovery(blob: Data(repeating: 1, count: 40), code: code))
      // The vector's code is a code as this app makes them.
      XCTAssertEqual(LeaveCryptoCore.normalizeRecoveryCode(code), code)
    }
  }

  func testRecoveryCodeShape() throws {
    let code = try LeaveCryptoCore.newRecoveryCode()
    XCTAssertEqual(code.count, 28)
    XCTAssertTrue(code.allSatisfy { LeaveCryptoCore.recoveryAlphabet.contains($0) })
    XCTAssertNotEqual(code, try LeaveCryptoCore.newRecoveryCode())
    // Typed with spaces, hyphens, lower case and the look-alikes the alphabet leaves out.
    XCTAssertEqual(LeaveCryptoCore.normalizeRecoveryCode("k7q2 m9x4-t6w1 z8r3 n5po v2c7 h4jd"), "K7Q2M9X4T6W1Z8R3N5P0V2C7H4JD")
    XCTAssertEqual(LeaveCryptoCore.normalizeRecoveryCode("I7Q2M9X4T6W1Z8R3N5P0V2C7H4JL"), "17Q2M9X4T6W1Z8R3N5P0V2C7H4J1")
    XCTAssertNil(LeaveCryptoCore.normalizeRecoveryCode("K7Q2M9X4"))
    XCTAssertNil(LeaveCryptoCore.normalizeRecoveryCode("U7Q2M9X4T6W1Z8R3N5P0V2C7H4JD"), "U is not in the alphabet")
    XCTAssertEqual(LeaveCryptoCore.groupedRecoveryCode("K7Q2M9X4T6W1Z8R3N5P0V2C7H4JD"), "K7Q2 M9X4 T6W1 Z8R3 N5P0 V2C7 H4JD")
  }

  func testShareWrap() throws {
    for c in cases("shareWrap") {
      let share = try b(try s(c, "share"))
      XCTAssertEqual(LeaveCryptoCore.base64url(LeaveCryptoCore.wrapKey(share: share, recordId: try s(c, "recordId"))), try s(c, "wrapKey"))
      let wire = try LeaveCryptoCore.shareWrap(share: share, recordType: try s(c, "recordType"), recordId: try s(c, "recordId"), dek: try b(try s(c, "dek")), nonce: try b(try s(c, "nonce")))
      XCTAssertEqual(LeaveCryptoCore.base64url(wire), try s(c, "wire"))
      XCTAssertEqual(try LeaveCryptoCore.shareUnwrap(share: share, recordType: try s(c, "recordType"), recordId: try s(c, "recordId"), wire: wire), try b(try s(c, "dek")))
    }
  }

  func testAccountKey() throws {
    for c in cases("accountKey") {
      let scalar = LeaveCryptoCore.accountScalar(share: try b(try s(c, "share")), accountId: try s(c, "accountId"))
      XCTAssertEqual(LeaveCryptoCore.base64url(scalar), try s(c, "privateScalar"))
      let key = try LeaveCryptoCore.accountAgreementKey(share: try b(try s(c, "share")), accountId: try s(c, "accountId"))
      XCTAssertEqual(LeaveCryptoCore.base64url(key.publicKey.derRepresentation), try s(c, "publicKeySpki"))
      XCTAssertEqual(LeaveCryptoCore.base64url(key.publicKey.x963Representation), try s(c, "publicKeyRaw"))
    }
    XCTAssertFalse(LeaveCryptoCore.scalarInRange(Data(repeating: 0, count: 32)))
    XCTAssertFalse(LeaveCryptoCore.scalarInRange(Data(repeating: 0xff, count: 32)))
    XCTAssertTrue(LeaveCryptoCore.scalarInRange(Data(repeating: 0, count: 31) + Data([1])))
  }

  func testHpke() throws {
    for c in cases("hpke") {
      let recipient = try P256.KeyAgreement.PrivateKey(rawRepresentation: try b(try s(c, "recipientScalar")))
      XCTAssertEqual(LeaveCryptoCore.base64url(recipient.publicKey.derRepresentation), try s(c, "recipientPublicKeySpki"))
      // CryptoKit cannot inject the ephemeral key, so: open the vector's wire, and round-trip our own seal.
      XCTAssertEqual(try LeaveCryptoCore.hpkeOpen(recipientKey: recipient, info: try s(c, "info"), wire: try b(try s(c, "wire"))), try b(try s(c, "plaintext")), c["name"] as? String ?? "")
      let mine = try LeaveCryptoCore.hpkeSeal(recipientSpki: recipient.publicKey.derRepresentation, info: try s(c, "info"), plaintext: try b(try s(c, "plaintext")))
      XCTAssertEqual(mine.count, 65 + (try b(try s(c, "plaintext"))).count + 16)
      XCTAssertEqual(try LeaveCryptoCore.hpkeOpen(recipientKey: recipient, info: try s(c, "info"), wire: mine), try b(try s(c, "plaintext")))
      XCTAssertThrowsError(try LeaveCryptoCore.hpkeOpen(recipientKey: recipient, info: "leave:v1:xwrap:other", wire: mine))
    }
  }

  func testGrant() throws {
    let c = try XCTUnwrap(cases("grant").first)
    let pkcs8 = try b(try s(c, "rsaPrivateKeyPkcs8"))
    let spki = try b(try s(c, "rsaPublicKeySpki"))
    let sessionKey = try b(try s(c, "sessionKey"))
    // The vector's own seal opens to the session key; our seal opens the same way (OAEP is randomised).
    XCTAssertEqual(try LeaveCryptoCore.rsaOpen(privateKeyPkcs8: pkcs8, sealed: try b(try s(c, "sealedSessionKey"))), sessionKey)
    let mine = try LeaveCryptoCore.rsaSeal(serverSpki: spki, sessionKey: sessionKey)
    XCTAssertEqual(mine.count, 384)
    XCTAssertEqual(try LeaveCryptoCore.rsaOpen(privateKeyPkcs8: pkcs8, sealed: mine), sessionKey)
    for r in try XCTUnwrap(c["records"] as? [[String: Any]]) {
      let aad = LeaveCryptoCore.grantAad(sessionId: try s(c, "sessionId"), recordId: try s(r, "id"))
      XCTAssertEqual(aad, Data(try s(r, "aad").utf8))
      let sealed = try LeaveCryptoCore.sealDek(sessionKey: sessionKey, sessionId: try s(c, "sessionId"), recordId: try s(r, "id"), dek: try b(try s(r, "dek")), nonce: try b(try s(r, "nonce")))
      XCTAssertEqual(LeaveCryptoCore.base64url(sealed), try s(r, "sealedDek"))
    }
  }

  /// The phone's own work for one unlock over many records, at 500 and 2,000 records, with no
  /// network in it: a key the server made is opened and wrapped to the share (once per record), a
  /// share-wrapped key is opened, and each key is sealed into a grant. The times are printed; the
  /// bound is far above them, so the test fails only if the work stops being a fraction of a
  /// second.
  func testTimeOfAnUnlockOverManyStrands() throws {
    let c = try XCTUnwrap(cases("grant").first)
    let spki = try b(try s(c, "rsaPublicKeySpki"))
    let share = Data((0..<32).map { UInt8($0 &+ 7) })
    let accountKey = try LeaveCryptoCore.accountAgreementKey(share: share, accountId: "acc_timing")
    let accountSpki = accountKey.publicKey.derRepresentation
    for n in [500, 2000] {
      let ids = (0..<n).map { "str_timing_\($0)" }
      let deks = ids.map { _ in SymmetricKey(size: .bits256).withUnsafeBytes { Data($0) } }
      let wires = try zip(ids, deks).map { try LeaveCryptoCore.shareWrap(share: share, recordType: "strand", recordId: $0, dek: $1) }
      let pending = try zip(ids, deks).map { try LeaveCryptoCore.hpkeSeal(recipientSpki: accountSpki, info: "leave:v1:pending:\($0)", plaintext: $1) }

      var started = Date()
      for (id, wire) in zip(ids, pending) {
        let dek = try LeaveCryptoCore.hpkeOpen(recipientKey: accountKey, info: "leave:v1:pending:\(id)", wire: wire)
        _ = try LeaveCryptoCore.shareWrap(share: share, recordType: "strand", recordId: id, dek: dek)
      }
      let pendingMs = -started.timeIntervalSinceNow * 1000

      started = Date()
      let opened = try zip(ids, wires).map { try LeaveCryptoCore.shareUnwrap(share: share, recordType: "strand", recordId: $0, wire: $1) }
      let openMs = -started.timeIntervalSinceNow * 1000

      started = Date()
      let sessionKey = SymmetricKey(size: .bits256).withUnsafeBytes { Data($0) }
      _ = try LeaveCryptoCore.rsaSeal(serverSpki: spki, sessionKey: sessionKey)
      var bytes = 0
      for (id, dek) in zip(ids, opened) {
        bytes += try LeaveCryptoCore.sealDek(sessionKey: sessionKey, sessionId: "ses_timing", recordId: id, dek: dek).count
      }
      let sealMs = -started.timeIntervalSinceNow * 1000

      XCTAssertEqual(opened, deks)
      print(String(format: "UNLOCK-TIMING records=%d pendingWraps=%.0fms openKeys=%.0fms sealGrant=%.0fms sealedBytes=%d", n, pendingMs, openMs, sealMs, bytes))
      XCTAssertLessThan(openMs + sealMs, 5000, "opening and sealing \(n) keys")
    }
  }

  func testSignatures() throws {
    for c in cases("signatures") {
      let spki = try b(try s(c, "publicKeySpki"))
      let msg = try b(try s(c, "message"))
      XCTAssertTrue(try LeaveCryptoCore.verify(spki: spki, message: msg, signature: try b(try s(c, "signatureRaw"))), c["name"] as? String ?? "")
      XCTAssertTrue(try LeaveCryptoCore.verify(spki: spki, message: msg, signature: try b(try s(c, "signatureDer"))))
      XCTAssertFalse(try LeaveCryptoCore.verify(spki: spki, message: msg + Data([0]), signature: try b(try s(c, "signatureRaw"))))
    }
  }

  // MARK: - Samples from the server's own code (2026-09-29), with fixed, made-up keys. The
  // contract fields' sample names an invented brand; its expected bytes were sealed again for that
  // name with Node's AES-256-GCM, which reproduced the original sample's bytes first.

  private let dek11 = Data(repeating: 0x11, count: 32)

  func testServerSampleShareWrap() throws {
    let share = Data(repeating: 0x07, count: 32)
    XCTAssertEqual(LeaveCryptoCore.base64url(share), "BwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwc")
    XCTAssertEqual(LeaveCryptoCore.base64url(LeaveCryptoCore.wrapKey(share: share, recordId: "01J8Z3V4Q6X7R2M9K5T0W1Y8NE")), "1KCpaAu0sNEXu9aO6_oP0_hOXp6UOhls9CqPR_lAfuM")
    let wire = try LeaveCryptoCore.shareWrap(share: share, recordType: "contract", recordId: "01J8Z3V4Q6X7R2M9K5T0W1Y8NE", dek: dek11, nonce: Data(repeating: 0x55, count: 12))
    XCTAssertEqual(LeaveCryptoCore.base64url(wire), "VVVVVVVVVVVVVVVVf3-Gg294UwPHNj9unms0aGqwjee1oGS1nNBSg4Smll37k1DAmKj7Oyb7xJAO83W2")
  }

  func testServerSampleGrantDek() throws {
    let sessionKey = Data(repeating: 0x22, count: 32)
    let sealed = try LeaveCryptoCore.sealDek(sessionKey: sessionKey, sessionId: "01J8Z3V4Q6X7R2M9K5T0W1Y8SS", recordId: "01J8Z3V4Q6X7R2M9K5T0W1Y8NE", dek: dek11, nonce: Data(repeating: 0x33, count: 12))
    XCTAssertEqual(LeaveCryptoCore.base64url(sealed), "MzMzMzMzMzMzMzMzZ9LX-2Q9Z3kZ_IphBMAcgzSwepZJoXjgG8Y554-eE2yNmsXUbD9cewrhEa1uUNCk")
  }

