  func testServerSampleUploadCiphertext() throws {
    let wire = try LeaveCryptoCore.seal(key: dek11, plaintext: Data("%PDF-1.7 sample".utf8), aad: LeaveCryptoCore.aad("contract", "01J8Z3V4Q6X7R2M9K5T0W1Y8NE"), nonce: Data(repeating: 0x66, count: 12))
    XCTAssertEqual(LeaveCryptoCore.base64url(wire), "ZmZmZmZmZmZmZmZmnb3Hp9ckv43jepR-HfTtJDMmcdX2Sc5n7g8z4zUJtQ")
    XCTAssertEqual(wire.count, 43)
    XCTAssertEqual(LeaveCryptoCore.sha256Hex(wire), "ae2a2e0cb1e983358a5ec961be216b8bf89542098eb24b33f913c6c8050461df")
  }

  func testAsn1Helpers() throws {
    // The vectors' RSA keys go through the SPKI / PKCS#8 strippers on every seal and open.
    let c = try XCTUnwrap(cases("grant").first)
    XCTAssertLessThan(LeaveCryptoCore.stripSpkiHeaderIfRSA(try b(try s(c, "rsaPublicKeySpki"))).count, (try b(try s(c, "rsaPublicKeySpki"))).count)
    XCTAssertLessThan(LeaveCryptoCore.stripPkcs8HeaderIfRSA(try b(try s(c, "rsaPrivateKeyPkcs8"))).count, (try b(try s(c, "rsaPrivateKeyPkcs8"))).count)
  }
}
